12	import org.springframework.web.bind.annotation.RestControllerAdvice;
13	import org.springframework.web.method.annotation.HandlerMethodValidationException;
14	import org.springframework.web.method.annotation.MethodArgumentTypeMismatchException;
15	
16	/**
17	 * 统一错误映射：业务异常按自身状态码返回；参数绑定/校验失败返回 400。
18	 */
19	@RestControllerAdvice
20	public class GlobalExceptionHandler {
21	
22	    @ExceptionHandler(ApiException.class)
23	    public ResponseEntity<ErrorResponse> handleApi(ApiException e) {
24	        return ResponseEntity.status(e.status())
25	                .body(new ErrorResponse(e.code(), e.getMessage(), e.details()));
26	    }
27	
28	    @ExceptionHandler(MethodArgumentNotValidException.class)
29	    public ResponseEntity<ErrorResponse> handleValidation(MethodArgumentNotValidException e) {
30	        String message = e.getBindingResult().getFieldErrors().stream()
31	                .findFirst()
32	                .map(FieldError::getField)
33	                .map(field -> "参数非法: " + field)
34	                .orElse("参数非法");
35	        return badRequest(message);
36	    }
37	
38	    @ExceptionHandler({
39	            HttpMessageNotReadableException.class,
40	            MissingServletRequestParameterException.class,
41	            MethodArgumentTypeMismatchException.class,
42	            HandlerMethodValidationException.class
43	    })
44	    public ResponseEntity<ErrorResponse> handleBadRequest(Exception e) {
45	        return badRequest("请求参数非法: " + e.getClass().getSimpleName());
46	    }
47	
48	    private ResponseEntity<ErrorResponse> badRequest(String message) {
49	        return ResponseEntity.status(HttpStatus.BAD_REQUEST)
50	                .body(new ErrorResponse("INVALID_ARGUMENT", message, List.of()));
51	    }
52	}
